package com.cinenest.verification.internal;
import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import static org.assertj.core.api.Assertions.*;
class SyntheticEvidenceTest {
    byte[] png()throws Exception{var image=new java.awt.image.BufferedImage(40,40,java.awt.image.BufferedImage.TYPE_INT_RGB);var out=new ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);return out.toByteArray();}
    VerificationPolicy.Policy policy(byte[] fixture){return new VerificationPolicy.Policy("SYNTHETIC-V1","a".repeat(64),UUID.randomUUID(),Duration.ofSeconds(10),Duration.ofSeconds(60),Duration.ofSeconds(20),Duration.ofSeconds(1),Set.of(VerificationPolicy.hash(fixture)));}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"png","jpeg"}) void approvedImageProducesFreshRasterOnly(String format)throws Exception{var raster=new java.awt.image.BufferedImage(40,40,java.awt.image.BufferedImage.TYPE_INT_RGB);var encoded=new ByteArrayOutputStream();javax.imageio.ImageIO.write(raster,format,encoded);var image=encoded.toByteArray();var result=new SyntheticEvidenceProcessor().process(image,"image/"+format,policy(image));assertThat(result.digest()).isEqualTo(VerificationPolicy.hash(image));assertThat(javax.imageio.ImageIO.read(new ByteArrayInputStream(result.preview())).getWidth()).isEqualTo(40);}
    @Test void unknownRealOrUnsafeBytesAreNeverAdmitted()throws Exception{byte[] image=png();assertThatThrownBy(()->new SyntheticEvidenceProcessor().process("unknown".getBytes(),"image/png",policy(image))).isInstanceOf(VerificationFailure.class);}
    @Test void malformedAllowlistedBytesAndMimeMismatchAreRejected()throws Exception{byte[] malformed={(byte)137,80,78,71,13,10,26,10,0,0};assertThatThrownBy(()->new SyntheticEvidenceProcessor().process(malformed,"image/png",policy(malformed))).isInstanceOf(VerificationFailure.class);byte[] image=png();assertThatThrownBy(()->new SyntheticEvidenceProcessor().process(image,"image/jpeg",policy(image))).isInstanceOf(VerificationFailure.class);}
    @Test void byteLimitIsCheckedEvenForApprovedHash(){byte[] large=new byte[VerificationPolicy.MAX_BYTES+1];assertThatThrownBy(()->new SyntheticEvidenceProcessor().process(large,"image/png",policy(large))).isInstanceOf(VerificationFailure.class).hasMessageContaining("size");}
    @Test void decodedPixelBudgetIsEnforcedBeforeRasterAllocation()throws Exception{byte[] image=png();byte[] huge=image.clone();java.nio.ByteBuffer.wrap(huge,16,8).putInt(100000).putInt(100000);java.util.zip.CRC32 crc=new java.util.zip.CRC32();crc.update(huge,12,17);java.nio.ByteBuffer.wrap(huge,29,4).putInt((int)crc.getValue());assertThatThrownBy(()->new SyntheticEvidenceProcessor().process(huge,"image/png",policy(huge))).isInstanceOf(VerificationFailure.class);}
    @Test void missingZeroAndProductionPolicyFailClosed(){var env=new MockEnvironment();assertThatThrownBy(()->new VerificationPolicy(env).current()).isInstanceOf(VerificationFailure.class);env.setActiveProfiles("synthetic-quotation");env.withProperty("cinenest.verification.enabled","true").withProperty("cinenest.verification.policy-version","SYNTHETIC-V1").withProperty("cinenest.verification.fixture-sha256",VerificationPolicy.hash(SyntheticFixtures.image("png")));for(var key:List.of("upload","retention","decision","cleanup"))env.withProperty("cinenest.verification."+key+"-seconds","1");assertThat(new VerificationPolicy(env).current().version()).isEqualTo("SYNTHETIC-V1");env.withProperty("cinenest.verification.upload-seconds","0");assertThatThrownBy(()->new VerificationPolicy(env).current()).isInstanceOf(VerificationFailure.class);}
    @Test void encryptedStorageAuthenticatesContentAndSupportsIdempotentDeletion()throws Exception{var root=Files.createTempDirectory("synthetic-encryption-test-");var env=new MockEnvironment().withProperty("cinenest.verification.storage-root",root.toString()).withProperty("cinenest.verification.encryption-key",Base64.getEncoder().encodeToString(new byte[32]));var store=new EncryptedEvidenceStore(env);UUID id=UUID.randomUUID();byte[] plain=png();store.put(id,plain);assertThat(store.get(id)).isEqualTo(plain);assertThat(Files.readAllBytes(root.resolve(EncryptedEvidenceStore.OBJECT_PREFIX+id+".enc"))).isNotEqualTo(plain);byte[] altered=Files.readAllBytes(root.resolve(EncryptedEvidenceStore.OBJECT_PREFIX+id+".enc"));altered[20]^=1;Files.write(root.resolve(EncryptedEvidenceStore.OBJECT_PREFIX+id+".enc"),altered);assertThatThrownBy(()->store.get(id)).isInstanceOf(VerificationFailure.class);store.delete(id);store.delete(id);assertThat(Files.exists(root.resolve(EncryptedEvidenceStore.OBJECT_PREFIX+id+".enc"))).isFalse();Files.delete(root);}
    @Test void repositoryAndSymbolicLinkStorageRootsAreDenied()throws Exception{var env=new MockEnvironment().withProperty("cinenest.verification.storage-root",Path.of(".").toAbsolutePath().toString());assertThatThrownBy(()->new EncryptedEvidenceStore(env).put(UUID.randomUUID(),new byte[]{1})).isInstanceOf(VerificationFailure.class);var root=Files.createTempDirectory("synthetic-link-test-");var link=root.resolve("link");Files.createSymbolicLink(link,Path.of("/tmp"));env.withProperty("cinenest.verification.storage-root",link.toString());assertThatThrownBy(()->new EncryptedEvidenceStore(env).delete(UUID.randomUUID())).isInstanceOf(VerificationFailure.class);Files.delete(link);Files.delete(root);}
}
